22: /**
23:  * 订阅后端主动陪伴 SSE 实时流与即时问候事件，统一呈现系统提示音、应用内去回复提示并刷新桌面会话内容。
24:  */
25: export function useCompanionNotifications({
26:   showMessage,
27:   setIsSettingsOpen,
28:   setActiveFeature,
29:   setActiveSessionId,
30:   fetchSessionDetail,
31:   setSessions,
32: }: UseCompanionNotificationsOptions) {
33:   const ackedNoticesRef = useRef<Set<string>>(new Set());
34: 
35:   useEffect(() => {
36:     let stopped = false;
37: 
38:     const processCompanionView = (companion: LifeCompanionView | null | undefined) => {
39:       if (stopped || !companion?.pendingDesktopNotices?.length) return;
40:       for (const notice of companion.pendingDesktopNotices) {
41:         if (notice.acknowledged || ackedNoticesRef.current.has(notice.id)) continue;
42:         ackedNoticesRef.current.add(notice.id);
43:         void lifeReviewApi.ackDesktopNotice(notice.id).catch(() => {});
44: 
45:         const ts = Date.parse(notice.createdAt) || Date.now();
46:         void deliverTaskNotification({
47:           id: notice.id,
48:           taskId: 'companion',
49:           title: notice.title || 'Agent 主动问候',
50:           content: notice.content,
51:           plannedAt: ts,
52:           createdAt: ts,
53:           source: 'COMPANION',
54:           status: 'RUNNING',
55:           desktopStatus: 'PENDING',
56:           emailStatus: 'SKIPPED',
57:           confirmation: 'NONE',
58:           sound: true,
59:           error: '',
60:         }).catch(() => {});
61: 
62:         showMessage('info', `💬 ${notice.title || 'Agent 主动问候'}：${notice.content.slice(0, 120)}`, {
63:           duration: 10000,
64:           action: {
65:             label: '去回复',
66:             onClick: () => {
67:               setIsSettingsOpen(false);
68:               setActiveFeature('chat');
69:               if (notice.sessionId) setActiveSessionId(notice.sessionId);
70:             },
71:           },
72:         });
73: 
74:         if (notice.sessionId) {
75:           void fetchSessionDetail(notice.sessionId).then((detail) => {
76:             if (!detail || stopped) return;
77:             const messages = detail.messages.map(mapTranscriptToChatMessage);
78:             setSessions((previous) => previous.map((session) => (session.id === notice.sessionId
79:               ? {
80:                   ...session,
81:                   title: detail.summary.title,
82:                   lastMessagePreview: detail.summary.lastMessagePreview,
83:                   messages,
84:                   usageSummary: detail.usageSummary,
85:                   isLoaded: true,
86:                 }
87:               : session)));
88:           }).catch(() => {});
89:         }
90:       }
91:     };
92: 
93:     const subscription = lifeReviewApi.subscribeCompanion(processCompanionView);
94:     const onOutreachUpdated = (event: Event) => {
95:       const custom = event as CustomEvent<LifeCompanionView>;
96:       if (custom.detail) processCompanionView(custom.detail);
97:     };
98:     window.addEventListener('companion-outreach-updated', onOutreachUpdated);
99:     return () => {
100:       stopped = true;
101:       subscription.close();
102:       window.removeEventListener('companion-outreach-updated', onOutreachUpdated);
103:     };
104:   }, [fetchSessionDetail, setActiveFeature, setActiveSessionId, setIsSettingsOpen, setSessions, showMessage]);
105: }

