import { useState } from 'react';
import { RefreshCw, Settings2, Sparkles } from 'lucide-react';
import { lifeReviewApi } from '../../services/lifeReviewApi';
import { Button } from '../common/Button';
import { ConfirmDialog } from '../common/ConfirmDialog';
import { LoadingTree } from '../common/LoadingTree';
import { TopBar } from '../common/TopBar';
import { TopBarAction } from '../common/TopBarAction';
import { MemoryDocumentManager } from '../memory/MemoryDocumentManager';
import { PersonalProfileSection } from '../settings/PersonalProfileSection';
import { SettingsGroup, SettingsRow } from '../settings/SettingsGroup';
import { LifeCompanionSection } from './LifeCompanionSection';
import { LifeContentCard } from './LifeContentCard';
import { LifeGoalSettings } from './LifeGoalSettings';
import { LifeOutreachSection } from './LifeOutreachSection';
import { ReviewDisclosure } from './ReviewDisclosure';
import { ReviewEmptyState } from './ReviewEmptyState';
import { useLifeReview } from './useLifeReview';
import reviewStyles from './LifeReviewSettings.module.css';
import styles from './LifeStatusPage.module.css';

interface LifeStatusPageProps {
  onOpenSettings?: (tab?: 'review' | 'context') => void;
}

/** 侧边栏「状态」一级工作台：集中管理每日复盘、个人目标、Agent 系统性认知、个人画像与经历来源、作息及主动提醒记录。 */
export function LifeStatusPage({ onOpenSettings }: LifeStatusPageProps = {}) {
  const state = useLifeReview();
  const { settings: s, busy, act } = state;
  const [habitModalOpen, setHabitModalOpen] = useState(false);
  const [hour, setHour] = useState(21);
  const [habitSource, setHabitSource] = useState('');
  const [refreshOpen, setRefreshOpen] = useState(false);

  const disabled = busy || state.dirty || !s?.enabled || !s.authorized;

  function today() {
    const parts = new Intl.DateTimeFormat('en', {
      timeZone: s?.timezone || 'Asia/Shanghai',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
    }).formatToParts(new Date());
    return ['year', 'month', 'day']
      .map(type => parts.find(part => part.type === type)?.value || '')
      .join('-');
  }

  const orderedHistory = [...state.history].sort((a, b) => b.day.localeCompare(a.day) || b.version - a.version);
  const todayContent = orderedHistory.find(c => c.day === today());

  return (
    <main className={styles.page}>
      <TopBar
        icon={<Sparkles size={19} />}
        title="状态"
        subtitle="日常复盘、个人目标与自我认知"
        actions={
          <div className={styles.headerActions}>
            <TopBarAction
              variant="ghost"
              icon={<RefreshCw size={14} />}
              disabled={busy || state.loading}
              onClick={() => void state.load()}
            >
              {state.loading ? '正在读取…' : '刷新数据'}
            </TopBarAction>
            {onOpenSettings && (
              <>
                <TopBarAction variant="ghost" onClick={() => onOpenSettings('context')}>
                  个人上下文设置
                </TopBarAction>
                <TopBarAction
                  variant="ghost"
                  iconOnly
                  aria-label="生活复盘设置"
                  icon={<Settings2 size={18} />}
                  onClick={() => onOpenSettings('review')}
                >
                  <span className={styles.visuallyHidden}>生活复盘设置</span>
                </TopBarAction>
              </>
            )}
          </div>
        }
      />

      <div className={styles.workspace}>
        <div className={styles.content}>
          <div className={styles.contentInner}>
            {state.loading && !s && (
              <div className={styles.loadingCenter}>
                <LoadingTree size="large" label="正在读取个人状态与复盘…" />
              </div>
            )}

            {state.error && (
              <p role="alert" className={reviewStyles.error}>
                {state.error}
                <Button size="sm" onClick={() => void state.load()}>重新读取</Button>
              </p>
            )}

            {s && (
              <>
                <SettingsGroup title="我的复盘" description="每份内容标明归属日、覆盖截止点与版本。补充产生新版本，保留已发送副本；准备中可稍后刷新。">
                  {(!s.enabled || !s.authorized) && (
                    <SettingsRow
                      label={!s.enabled ? '生活复盘尚未启用' : '生活复盘尚未完成用途授权'}
                      description="启用并确认读取范围与模型授权后，即可按设定时间或手动准备今日复盘。"
                      control={
                        onOpenSettings ? (
                          <Button size="sm" variant="outline" onClick={() => onOpenSettings('review')}>
                            前往复盘设置
                          </Button>
                        ) : null
                      }
                    />
                  )}
                  <SettingsRow
                    label="准备今天"
                    description={state.generating ? '正在后台调用模型生成复盘，完成后会自动刷新…' : `每日 ${state.habit?.active ? state.habit.availableHour : 21}:00 自动准备。已有当天版本时直接查看；更新资料请点“更新今天的复盘”。`}
                    control={
                      <div className={reviewStyles.choices}>
                        <Button size="sm" variant="primary" disabled={disabled || state.generating} onClick={() => {
                          const day = today();
                          const readyToday = state.history.some(c => c.day === day && c.state === 'READY');
                          void act(() => lifeReviewApi.prepare(day, 0, false), readyToday ? '正在查看今天已有版本；需要重新采集资料时请点“更新今天的复盘”' : '已开始后台生成今日复盘，请稍候…');
                        }}>
                          {state.generating ? '正在生成复盘…' : '准备今天的复盘'}
                        </Button>
                        {todayContent && !state.generating && (
                          <Button size="sm" disabled={disabled || todayContent.state === 'UNKNOWN'} onClick={() => setRefreshOpen(true)}>
                            更新今天的复盘
                          </Button>
                        )}
                        <Button size="sm" disabled={disabled} onClick={() => {
                          setHour(state.habit?.active ? state.habit.availableHour : 21);
                          setHabitSource(state.habit?.source || '');
                          setHabitModalOpen(true);
                        }}>
                          设置每日时间（{state.habit?.active ? `${state.habit.availableHour}:00` : '21:00'}）
                        </Button>
                        <Button size="sm" disabled={busy || state.dirty} onClick={() => void state.load()}>
                          刷新内容与状态
                        </Button>
                      </div>
                    }
                  />
                  {state.history.length === 0 && (
                    <ReviewEmptyState title="还没有生活复盘" description="准备一份当天复盘后，内容和历史版本会保留在这里。" />
                  )}
                  {!todayContent && orderedHistory.length > 0 && <p className={reviewStyles.muted}>今天尚无复盘，以下为最近一天的记录。</p>}
                  {orderedHistory.slice(0, 1).map(c => (
                    <LifeContentCard key={c.id} content={c} timezone={c.timezone || s.timezone} busy={busy} authorized={!disabled} feishu={s.feishu} act={act} />
                  ))}
                  {state.history.length > 1 && (
                    <ReviewDisclosure variant="inline" title={`历史版本（${state.history.length - 1}）`} description="旧版保留原内容；展开查看，不会重新生成。">
                      {orderedHistory.slice(1).map(c => (
                        <LifeContentCard key={c.id} content={c} timezone={c.timezone || s.timezone} busy={busy} authorized={!disabled} feishu={s.feishu} act={act} />
                      ))}
                    </ReviewDisclosure>
                  )}
                  {state.archives.map((a, i) => (
                    <details key={i}>
                      <summary>重置前的只读外发副本 {i + 1}</summary>
                      <p className={reviewStyles.archive}>{a}</p>
                    </details>
                  ))}
                </SettingsGroup>

                <ConfirmDialog
                  open={refreshOpen}
                  title="更新今天的复盘"
                  tone="info"
                  confirmText="确认更新"
                  busy={busy}
                  description="重新采集已授权范围内截至现在的资料，并生成新版本，可能占用一次模型调用额度。旧版本与已发送副本保留。"
                  onClose={() => setRefreshOpen(false)}
                  onConfirm={() => {
                    setRefreshOpen(false);
                    if (todayContent) void act(() => lifeReviewApi.prepare(today(), todayContent.version, true), '已安排更新今天的复盘');
                  }}
                />

                <LifeGoalSettings />

                {state.companion && (
                  <LifeCompanionSection
                    companion={state.companion}
                    timezone={s.timezone}
                    busy={busy}
                    act={act}
                  />
                )}

                <PersonalProfileSection showMaintenanceToggle={false} />
                <MemoryDocumentManager />

                <LifeOutreachSection
                  settings={s}
                  habit={state.habit}
                  habitSuggestion={state.habitSuggestion}
                  candidates={state.candidates}
                  nudges={state.nudges}
                  busy={busy}
                  disabled={disabled}
                  habitModalOpen={habitModalOpen}
                  hour={hour}
                  habitSource={habitSource}
                  onHourChange={setHour}
                  onHabitSourceChange={setHabitSource}
                  onOpenHabitModal={(initialHour, initialSource) => {
                    setHour(initialHour);
                    setHabitSource(initialSource);
                    setHabitModalOpen(true);
                  }}
                  onCloseHabitModal={() => setHabitModalOpen(false)}
                  act={act}
                />
              </>
            )}
          </div>
        </div>
      </div>
    </main>
  );
}

import { useState } from 'react';
import { lifeReviewApi } from '../../services/lifeReviewApi';
import type { LifeSource } from '../../types/lifeReview';
import { Button } from '../common/Button';
import { Select } from '../common/Select';
import { TextInput } from '../common/TextInput';
import { SettingsGroup, SettingsRow } from '../settings/SettingsGroup';
import { SettingsPageLayout } from '../settings/SettingsPageLayout';
import { LifeSignalSettingsRows } from './LifeSignalSettingsRows';
import { ReviewDisclosure } from './ReviewDisclosure';
import { ReviewFormModal } from './ReviewFormModal';
import { useLifeReview } from './useLifeReview';
import styles from './LifeReviewSettings.module.css';

const SOURCES: { id: LifeSource; label: string }[] = [
  { id: 'BUSINESS', label: '待办与学习事实' },
  { id: 'JOURNAL', label: '每日手记正文' },
  { id: 'GOALS', label: '人工目标与主动反馈' },
  { id: 'CHAT', label: '普通聊天用户原文' },
  { id: 'FINANCE', label: '财务数值（含资产统计）' },
];

interface LifeReviewSettingsProps {
  onOpenStatus?: () => void;
}

/** 生活复盘独立设置入口；专注配置范围、提醒信号与用途授权，日常复盘内容与认知维护位于左侧「状态」模块。 */
export function LifeReviewSettings({ onOpenStatus }: LifeReviewSettingsProps = {}) {
  const state = useLifeReview();
  const { settings: s, busy, act, patch } = state;
  const [editor, setEditor] = useState<'settings' | 'consent' | null>(null);

  function closeEditor() {
    state.discard();
    setEditor(null);
  }

  const provider = state.providers.find(p => p.id === s?.providerId);

  return (
    <SettingsPageLayout
      title="生活复盘"
      description="配置生活复盘读取范围、固定模型、主动提醒与用途授权。"
      actions={
        <Button
          size="sm"
          variant="outline"
          disabled={busy || state.loading}
          onClick={() => void state.load()}
        >
          {state.loading ? '正在读取…' : '刷新数据'}
        </Button>
      }
      loading={state.loading}
      loadingLabel="正在读取生活复盘"
    >
      {state.error && (
        <p role="alert" className={styles.error}>
          {state.error}
          <Button size="sm" onClick={() => void state.load()}>重新读取</Button>
        </p>
      )}
      {s && (
        <>
          <SettingsGroup title="复盘设置" description="查看已保存的范围与运行状态，需要调整时再打开配置。">
            <SettingsRow
              label={s.enabled ? '生活复盘已启用' : '生活复盘未启用'}
              description={`${s.sources.map(id => SOURCES.find(source => source.id === id)?.label).join('、') || '尚未选择来源'} · ${s.modelName || '尚未选择模型'} · 回看${s.historyDays}日 · 每日≤${s.dailyLimit}次 · ${s.proactive ? '主动呈现' : '仅桌面留档'}${s.feishu ? ' · 飞书' : ''}${s.idleCheckinDays ? ` · ${s.idleCheckinDays}天未互动问候` : ''}${s.weatherAlertEnabled ? ' · 天气提醒' : ''}${s.expenseAlertEnabled ? ' · 支出提醒' : ''}${s.serverAlertEnabled ? ' · 服务器提醒' : ''}${s.mailAlertEnabled ? ` · 邮件提醒${s.mailStatus ? `：${s.mailStatus}` : ''}` : ''}`}
              control={<Button size="sm" disabled={busy} onClick={() => setEditor('settings')}>配置复盘</Button>}
            />
          </SettingsGroup>

          <ReviewFormModal
            open={editor === 'settings'}
            title="配置生活复盘"
            busy={busy}
            onClose={closeEditor}
            footer={
              <>
                <Button size="sm" onClick={closeEditor}>取消</Button>
                <Button
                  size="sm"
                  variant="primary"
                  disabled={busy || !s.sources.length || !s.modelName}
                  onClick={() => void act(async () => {
                    await lifeReviewApi.save(s);
                    setEditor(null);
                  }, '设置已保存，请确认新的授权范围')}
                >
                  保存生活复盘设置
                </Button>
              </>
            }
          >
            <SettingsGroup
              title="范围与固定模型"
              description="默认关闭。每日21点后可后台准备，按下方额度计费；扩大或修改设置后需要重新授权。"
            >
              <SettingsRow
                label="启用生活复盘"
                control={<input aria-label="启用生活复盘" type="checkbox" checked={s.enabled} disabled={busy} onChange={e => patch({ enabled: e.target.checked })} />}
              />
              <SettingsRow
                label="允许读取的来源"
                description="仅用于生活复盘，不继承聊天记忆或统计摘要授权。回看材料仍按原始时间标注。"
                layout="stacked"
                control={
                  <div className={styles.choices}>
                    {SOURCES.map(source => (
                      <label key={source.id}>
                        <input
                          type="checkbox"
                          checked={s.sources.includes(source.id)}
                          disabled={busy}
                          onChange={() => {
                            const nextSources = s.sources.includes(source.id)
                              ? s.sources.filter(id => id !== source.id)
                              : [...s.sources, source.id];
                            patch({
                              sources: nextSources,
                              expenseAlertEnabled: nextSources.includes('FINANCE') ? s.expenseAlertEnabled : false,
                            });
                          }}
                        />
                        {source.label}
                      </label>
                    ))}
                  </div>
                }
              />
              <SettingsRow
                label="模型连接"
                control={
                  <Select
                    aria-label="生活复盘模型连接"
                    value={s.providerId}
                    disabled={busy}
                    options={[
                      { value: '', label: '请选择模型连接' },
                      { value: 'ACTIVE', label: '跟随当前聊天默认模型（推荐）' },
                      ...state.providers.filter(p => p.isEnabled).map(p => ({ value: p.id, label: p.name })),
                    ]}
                    onChange={e => patch({
                      providerId: e.target.value,
                      modelName: e.target.value === 'ACTIVE' ? 'ACTIVE' : '',
                    })}
                  />
                }
              />
              <SettingsRow
                label="固定模型"
                control={
                  <Select
                    aria-label="生活复盘固定模型"
                    value={s.modelName}
                    disabled={busy || s.providerId === 'ACTIVE'}
                    options={
                      s.providerId === 'ACTIVE'
                        ? [{ value: 'ACTIVE', label: '自动跟随当前聊天模型' }]
                        : [{ value: '', label: '请选择模型' }, ...(provider?.models || []).map(m => ({ value: m.name, label: m.name }))]
                    }
                    onChange={e => patch({ modelName: e.target.value })}
                  />
                }
              />
              <ReviewDisclosure variant="inline" title="高级设置" description="近期原文范围、时区与费用保护；不是长期记忆的保存期限。">
                <SettingsRow
                  label="时区"
                  control={<TextInput aria-label="生活复盘时区" value={s.timezone} disabled={busy} onChange={e => patch({ timezone: e.target.value })} />}
                />
                <SettingsRow
                  label="近期原文范围（含当天）"
                  description="每次最多读取最近7天原文；更早经历会按已授权记忆自动关联。"
                  control={<TextInput aria-label="生活复盘回看天数" type="number" min={1} max={7} value={s.historyDays} disabled={busy} onChange={e => patch({ historyDays: Number(e.target.value) })} />}
                />
                <SettingsRow
                  label="每日模型调用上限"
                  description="失败调用同样占用额度；打开历史不会重新生成。"
                  control={<TextInput aria-label="生活复盘每日上限" type="number" min={1} max={3} value={s.dailyLimit} disabled={busy} onChange={e => patch({ dailyLimit: Number(e.target.value) })} />}
                />
              </ReviewDisclosure>
              <LifeSignalSettingsRows settings={s} busy={busy} patch={patch} />
            </SettingsGroup>
            <p className={styles.muted}>{state.dirty ? '有未保存更改；保存后再确认授权。' : '配置保存与授权分别执行。'}</p>
          </ReviewFormModal>

          <SettingsGroup title="用途授权" description="生成会把所选来源发送给上方固定模型；改变范围需重新授权，撤权不能撤回已发内容。">
            <SettingsRow
              label="当前状态"
              description={s.authorized ? '当前保存版本已授权。' : '尚未授权，不会读取材料或调用模型。'}
              control={
                s.authorized ? (
                  <Button size="sm" disabled={busy || state.dirty} onClick={() => void act(() => lifeReviewApi.consent(s, false), '授权已撤销，未呈现候选已取消')}>
                    撤销授权
                  </Button>
                ) : (
                  <Button size="sm" disabled={busy || state.dirty || !s.enabled || !s.revision} onClick={() => setEditor('consent')}>
                    核对并授权
                  </Button>
                )
              }
            />
            <ReviewFormModal open={editor === 'consent'} title="确认生活复盘授权" busy={busy} onClose={closeEditor}>
              <p className={styles.muted}>
                固定模型：{s.providerId} / {s.modelName}；来源：{s.sources.map(id => SOURCES.find(source => source.id === id)?.label).join('、')}。
                时区：{s.timezone} · 回看{s.historyDays}日 · 每日≤{s.dailyLimit}次调用 · {s.proactive ? '允许主动呈现' : '仅桌面留档'} · {s.feishu ? '允许投递本人飞书' : '不投递飞书'}{s.idleCheckinDays ? ` · 连续${s.idleCheckinDays}天无互动飞书问候一次` : ''}{s.weatherAlertEnabled ? ' · 开启天气变化提醒' : ''}{s.expenseAlertEnabled ? ' · 开启支出变化提醒' : ''}{s.serverAlertEnabled ? ` · 开启服务器状态提醒（${s.serverProbeName || '应用服务器'}）` : ''}{s.mailAlertEnabled ? ` · 开启重要邮件提醒（${s.imapHost || 'IMAP'}）` : ''}。
              </p>
              {!s.authorized && (
                <SettingsRow
                  label="确认授权范围"
                  layout="stacked"
                  control={
                    <div className={styles.stack}>
                      <Button
                        size="sm"
                        variant="primary"
                        disabled={busy || state.dirty || !s.enabled || !s.revision}
                        onClick={() => void act(async () => {
                          await lifeReviewApi.consent(s, true);
                          setEditor(null);
                        }, '当前范围已单独授权')}
                      >
                        确认授权生活复盘
                      </Button>
                    </div>
                  }
                />
              )}
            </ReviewFormModal>
          </SettingsGroup>

          <SettingsGroup title="状态与内容" description="每日复盘正文、个人目标、Agent 系统性认知、个人画像、经历来源管理与主动联系记录已集中在左侧「状态」模块维护。">
            <SettingsRow
              label="日常状态与复盘"
              description={`每日 ${state.habit?.active ? state.habit.availableHour : 21}:00 自动准备复盘；当前已保存 ${state.history.length} 份复盘版本。`}
              control={
                onOpenStatus ? (
                  <Button size="sm" variant="outline" disabled={busy || state.dirty} onClick={onOpenStatus}>
                    前往状态
                  </Button>
                ) : null
              }
            />
          </SettingsGroup>
        </>
      )}
    </SettingsPageLayout>
  );
}

